+const nodeGroup=new THREE.Group();scene.add(nodeGroup);const nodes=[];function makeNode(x,z,ore){let g=new THREE.Group();g.position.set(x,0,z);const mat=new THREE.MeshStandardMaterial({color:ore.color,roughness:.3,metalness:.28,emissive:ore.color,emissiveIntensity:.13});let count=3+Math.floor(Math.random()*3);for(let i=0;i<count;i++){let crystal=new THREE.Mesh(new THREE.OctahedronGeometry(.48+Math.random()*.55,0),mat);crystal.position.set((Math.random()-.5)*1.3,.55+Math.random()*.65,(Math.random()-.5)*1.1);crystal.rotation.set(Math.random()*.5,Math.random()*3,Math.random()*.35);crystal.scale.y=1.5;crystal.castShadow=true;g.add(crystal)}let base=new THREE.Mesh(new THREE.DodecahedronGeometry(.8,0),new THREE.MeshStandardMaterial({color:0x384239,roughness:1}));base.scale.set(1,.5,.75);base.position.y=.32;base.castShadow=true;g.add(base);let halo=new THREE.Mesh(new THREE.RingGeometry(1.05,1.17,24),new THREE.MeshBasicMaterial({color:ore.color,transparent:true,opacity:.48,side:THREE.DoubleSide}));halo.rotation.x=-Math.PI/2;halo.position.y=.045;g.add(halo);g.userData={ore,hp:3+(ore.weight<15?1:0),max:3+(ore.weight<15?1:0),halo,crystals:g.children.slice(0,count)};nodeGroup.add(g);nodes.push(g);return g}
