for(let i=0;i<140;i++){let rock=new THREE.Mesh(new THREE.DodecahedronGeometry(.12+Math.random()*.2,0),new THREE.MeshStandardMaterial({color:Math.random()>.5?0x756c4c:0x5c6846,roughness:1}));rock.position.set((Math.random()-.5)*100,.12,(Math.random()-.5)*100);rock.rotation.set(Math.random(),Math.random(),Math.random());rock.castShadow=true;scene.add(rock)}
let nearest=null,mining=false,mineTimer=0,walkX=0,walkZ=0,last=performance.now(),walkPhase=0,toastTimer=0,questClaimed=false;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function notify(msg){let t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),1900)}
function xpNeed(){return 100+(state.level-1)*65}
function addXP(n){state.xp+=n;while(state.xp>=xpNeed()){state.xp-=xpNeed();state.level++;state.copper+=20;notify(`Seviye ${state.level}! +20 bakır`)};updateUI()}
function updateUI(){for(let k of ['copper','crystal','gold'])$('#'+k).textContent=Math.floor(state[k]).toLocaleString('tr-TR');$('#level').textContent=state.level;$('#xp-label').textContent=`${state.xp} / ${xpNeed()} XP`;$('#xp-fill').style.width=`${state.xp/xpNeed()*100}%`;$('#tool-name').textContent=tools[state.tool][0];$('#tool-icon').textContent=tools[state.tool][1];$('#tool-cost').textContent=tools[state.tool][3]||'MAX';$('#tool-upgrade').disabled=state.tool===tools.length-1;$('#quest-count').textContent=`${Math.min(10,state.mined)} / 10 parça`;$('#quest-fill').style.width=`${Math.min(100,state.mined*10)}%`;localStorage.setItem('derin-maden',JSON.stringify(state))}
try{Object.assign(state,JSON.parse(localStorage.getItem('derin-maden')||'{}'))}catch{}
function nearestNode(){let best=null,dist=Infinity;for(let n of nodes){if(!n.visible)continue;let d=Math.hypot(n.position.x-player.position.x,n.position.z-player.position.z);if(d<dist){best=n;dist=d}}return dist<5.4?best:null}
function mineHit(){if(!nearest){notify('Önce bir maden damarına yaklaş!');return}let ore=nearest.userData.ore;let pow=tools[state.tool][2]+state.skill.power*.65;let bonus=characters[state.character].bonus==='yield'?1.25:1;let qty=Math.max(1,Math.floor((ore.yield+state.skill.power*.35)*bonus));state[ore.key]=(state[ore.key]||0)+qty;state.mined+=qty;nearest.userData.hp--;nearest.scale.multiplyScalar(.94);nearest.userData.crystals.forEach(c=>{c.material.emissiveIntensity=.9;setTimeout(()=>c.material.emissiveIntensity=.13,120)});addXP(ore.xp);if(state.mined>=10&&!questClaimed){questClaimed=true;addXP(25);state.gold+=5;notify('Görev tamamlandı! +25 XP · +5 altın')}if(nearest.userData.hp<=0){let depleted=nearest;depleted.visible=false;let newOre=pickOre();setTimeout(()=>{depleted.position.set((Math.random()-.5)*95,0,(Math.random()-.5)*95);depleted.userData.ore=newOre;depleted.userData.hp=depleted.userData.max;depleted.scale.set(1,1,1);depleted.visible=true},13000);if(Math.random()<.08+state.skill.luck*.025){let find=ores[Math.min(ores.indexOf(ore)+1,ores.length-1)];state[find.key]=(state[find.key]||0)+1;notify(`Nadir buluntu: ${find.name} +1`)}else notify(`${ore.name} damarı tükendi`)}updateUI()}
$('#tool-upgrade').onclick=()=>{let next=tools[state.tool+1];if(!next){notify('Kazman zaten en güçlü seviyede!');return}if(state.copper<next[3]){notify(`Yetersiz bakır · ${next[3]} gerekli`);return}state.copper-=next[3];state.tool++;updateUI();notify(`${next[0]} kuşanıldı!`)};
const joy=$('#joystick'),thumb=$('#joy-thumb');let joyPointer=null;function joyMove(e){let r=joy.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),max=r.width*.31,len=Math.hypot(dx,dy);if(len>max){dx=dx/len*max;dy=dy/len*max}walkX=dx/max;walkZ=dy/max;thumb.style.transform=`translate(calc(-50% + ${dx}px),calc(-50% + ${dy}px))`}joy.addEventListener('pointerdown',e=>{joyPointer=e.pointerId;joy.setPointerCapture(e.pointerId);joyMove(e)});joy.addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)joyMove(e)});function joyEnd(){joyPointer=null;walkX=walkZ=0;thumb.style.transform='translate(-50%,-50%)'}joy.addEventListener('pointerup',joyEnd);joy.addEventListener('pointercancel',joyEnd);
const mine=$('#mine');mine.addEventListener('pointerdown',e=>{e.preventDefault();mining=true;mine.classList.add('mining');mineHit();mineTimer=0});for(let ev of ['pointerup','pointercancel','pointerleave'])mine.addEventListener(ev,()=>{mining=false;mine.classList.remove('mining')});
const keys={};window.addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if(e.key===' '){e.preventDefault();mining=true;mineHit()}});window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;if(e.key===' ')mining=false});
function tick(now){let dt=Math.min(.05,(now-last)/1000);last=now;let ix=walkX+(keys.a||keys.arrowleft?-1:0)+(keys.d||keys.arrowright?1:0),iz=walkZ+(keys.w||keys.arrowup?-1:0)+(keys.s||keys.arrowdown?1:0);let mag=Math.hypot(ix,iz);if(mag>1){ix/=mag;iz/=mag}let speed=5.1*(1+state.skill.walk*.12);if(mag>.05){player.position.x=clamp(player.position.x+ix*speed*dt,-68,68);player.position.z=clamp(player.position.z+iz*speed*dt,-68,68);player.rotation.y=Math.atan2(ix,iz);walkPhase+=dt*10;player.children[0].position.y=1.15+Math.sin(walkPhase)*.04}else player.children[0].position.y=1.15;if(mining){let rate=(characters[state.character].bonus==='speed'?1.2:1)/(tools[state.tool][2]*.55+1.25)/(1+state.skill.speed*.16);mineTimer+=dt;if(mineTimer>rate){mineTimer=0;mineHit()}}nearest=nearestNode();let target=$('#target-name'),info=$('#target-info');if(nearest){let o=nearest.userData.ore;target.textContent=o.name;target.style.color='#'+o.color.toString(16).padStart(6,'0');info.innerHTML=`${o.emoji} <em>${nearest.userData.hp}/${nearest.userData.max} vuruş</em> · KAZ'a bas`;nearest.userData.halo.material.opacity=.35+Math.sin(now*.004)*.18}else{target.textContent='Yakında maden yok';target.style.color='';info.textContent='Damar bulmak için keşfe çık'}
let desired=new THREE.Vector3(player.position.x,player.position.y+15,player.position.z+17);camera.position.lerp(desired,1-Math.exp(-dt*3));camera.lookAt(player.position.x,0,player.position.z-1);renderer.render(scene,camera);requestAnimationFrame(tick)}requestAnimationFrame(tick);
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});

